      source: '#include <pthread.h>\n#include <stdio.h>\n#define N 1000000\nint data[N];\nlong part[4];                         /* one slot per thread */\n\nvoid *sum(void *arg) {\n    long id = (long)arg;\n    for (int i = id * (N / 4); i < (id + 1) * (N / 4); i++) part[id] += data[i];\n    return NULL;\n}\n\nint main(void) {\n    for (int i = 0; i < N; i++) data[i] = 1;\n    pthread_t t[4];\n    for (long id = 0; id < 4; id++) pthread_create(&t[id], NULL, sum, (void *)id);\n    long total = 0;\n    for (int id = 0; id < 4; id++) { pthread_join(t[id], NULL); total += part[id]; }\n    printf("total = %ld\\n", total);  /* total = 1000000 */\n    return 0;\n}',
